/**
 * Attendee share metadata helpers — favicon + Open Graph titles.
 *
 * Favicon is always the SHOW logo (never a room branding override).
 * Open Graph images are generated by colocated opengraph-image.tsx routes.
 */

import type { Metadata } from 'next'
import type { EffectiveBranding } from '@/types'

/** Same asset as root layout metadata icons (public/, not app/favicon.ico). */
const ONDA_DEFAULT_ICON = '/onda-operator-icon.png'

/** Show-level favicon from logoUrl; Onda defaults when unset. */
export function attendeeFaviconIcons(
  showBranding: Pick<EffectiveBranding, 'logoUrl'> | null | undefined,
): NonNullable<Metadata['icons']> {
  const logo = showBranding?.logoUrl?.trim()
  if (!logo) {
    return {
      icon: [{ url: ONDA_DEFAULT_ICON, type: 'image/png' }],
      apple: [{ url: ONDA_DEFAULT_ICON, type: 'image/png' }],
    }
  }
  return {
    icon: [{ url: logo }],
    apple: [{ url: logo }],
  }
}

export function attendeePageMetadata(opts: {
  title: string
  description?: string
  /** Always pass SHOW branding — not room-effective branding. */
  showBranding: Pick<EffectiveBranding, 'logoUrl'> | null | undefined
}): Metadata {
  const description =
    opts.description?.trim() ||
    'Live translation, captions, and session notes powered by cre8ion Onda.'

  return {
    title: opts.title,
    description,
    icons: attendeeFaviconIcons(opts.showBranding),
    openGraph: {
      title: opts.title,
      description,
      type: 'website',
      // og:image comes from opengraph-image.tsx on each attendee route
    },
    twitter: {
      card: 'summary_large_image',
      title: opts.title,
      description,
    },
  }
}
